import 'package:flutter/material.dart';
import '../settings/farm_location_settings.dart';
import '../theme/app_theme.dart';

Future<void> showFarmLocationPicker(BuildContext context) async {
  await Navigator.of(context).push(MaterialPageRoute(builder: (_) => const FarmLocationPickerPage()));
}

class FarmLocationPickerPage extends StatefulWidget {
  const FarmLocationPickerPage({super.key});
  @override State<FarmLocationPickerPage> createState()=>_FarmLocationPickerPageState();
}

class _FarmLocationPickerPageState extends State<FarmLocationPickerPage>{
  late String province,city,town;
  static const _towns=<String,List<String>>{
    '경상북도|김천시':['아포읍','농소면','남면','개령면','감문면','어모면','봉산면','대항면','감천면','조마면','구성면','지례면','부항면','대덕면','증산면'],
  };
  @override void initState(){super.initState();final x=FarmLocationSettings.instance.location;province=x.province;city=x.cityCounty;town=x.town;}
  List<String> get townList=>_towns['$province|$city']??(town.isEmpty?const[]:[town]);
