  Widget _result()=>Container(padding:const EdgeInsets.all(10),decoration:BoxDecoration(border:Border.all(color:AppColors.divider),borderRadius:BorderRadius.circular(12)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('⌖  선택 결과',style:TextStyle(fontSize:11,fontWeight:FontWeight.w900)),const SizedBox(height:18),Text('$province > $city',style:const TextStyle(fontSize:9.5,height:1.4,color:AppColors.secondary)),const SizedBox(height:7),Text(town.isEmpty?city:town,style:const TextStyle(fontSize:16,fontWeight:FontWeight.w900))]));
